/*
 * Runtime for code generated by re/recomp/recomp.py.
 *
 * - cpu.r: register file laid out like Ghidra's x86 "register" space
 *   (EAX at 0x0, ECX 0x4, EDX 0x8, EBX 0xc, ESP 0x10, EBP 0x14, ESI 0x18,
 *   EDI 0x1c; flags CF 0x200, PF 0x202, AF 0x204, ZF 0x206, SF 0x207,
 *   DF 0x20a, OF 0x20b; x87 ST0.. at 0x1100, 16 bytes apart).
 * - mem: flat emulated 32-bit address space (RT_MEM_SIZE bytes). The original
 *   .data section lives at its original address, so pointers stored in data
 *   stay valid; the stack and the game's allocations are placed below/above.
 *
 * Little-endian host assumed (x86-64, ARM64).
 */
#pragma once
#include <stdint.h>
#include <string.h>

#define RT_MEM_SIZE 0x04000000u   /* 64 MB */

typedef struct {
    uint8_t  r[0x1200];
    uint32_t ret_addr;            /* address popped by the last RET */
} rt_cpu;

extern rt_cpu cpu;
extern uint8_t *mem;

typedef void (*rt_func)(void);
typedef struct { uint32_t addr; rt_func fn; } rt_func_entry;
extern const rt_func_entry rt_func_table[];
extern const unsigned rt_func_count;

/* ---- failures ------------------------------------------------------------ */
_Noreturn void rt_fail(const char *msg, const char *file, int line);
#define RT_FAIL(msg) rt_fail(msg, __FILE__, __LINE__)
_Noreturn void rt_bad_access(uint32_t addr, int size);

/* ---- registers -------------------------------------------------------------- */
static inline uint64_t RD_REG(unsigned off, int size) {
    uint64_t v = 0; memcpy(&v, &cpu.r[off], (size_t)size); return v;
}
static inline void WR_REG(unsigned off, int size, uint64_t v) {
    memcpy(&cpu.r[off], &v, (size_t)size);
}
static inline double RD_F80(unsigned off) { double d; memcpy(&d, &cpu.r[off], 8); return d; }
static inline void WR_F80(unsigned off, double d) { memcpy(&cpu.r[off], &d, 8); }

#define EAX ((uint32_t)RD_REG(0x00, 4))
#define ECX ((uint32_t)RD_REG(0x04, 4))
#define EDX ((uint32_t)RD_REG(0x08, 4))
#define EBX ((uint32_t)RD_REG(0x0c, 4))
#define ESP ((uint32_t)RD_REG(0x10, 4))
#define EBP ((uint32_t)RD_REG(0x14, 4))
#define ESI ((uint32_t)RD_REG(0x18, 4))
#define EDI ((uint32_t)RD_REG(0x1c, 4))
enum { R_EAX = 0x00, R_ECX = 0x04, R_EDX = 0x08, R_EBX = 0x0c, R_ESP = 0x10,
       R_EBP = 0x14, R_ESI = 0x18, R_EDI = 0x1c, R_CF = 0x200, R_ZF = 0x206,
       R_SF = 0x207, R_DF = 0x20a, R_OF = 0x20b };

/* ---- memory ----------------------------------------------------------------- */
static inline uint64_t MEM_RD(uint32_t a, int size) {
    if ((uint64_t)a + (uint64_t)size > RT_MEM_SIZE) rt_bad_access(a, size);
    uint64_t v = 0; memcpy(&v, &mem[a], (size_t)size); return v;
}
static inline void MEM_WR(uint32_t a, int size, uint64_t v) {
    if ((uint64_t)a + (uint64_t)size > RT_MEM_SIZE) rt_bad_access(a, -size);
    memcpy(&mem[a], &v, (size_t)size);
}

/* ---- arithmetic ------------------------------------------------------------- */
static inline int64_t SEXT(uint64_t v, int size) {
    if (size >= 8) return (int64_t)v;
    unsigned s = 64u - 8u * (unsigned)size;
    return (int64_t)(v << s) >> s;
}
static inline uint64_t SHL(uint64_t v, uint64_t n) { return n >= 64 ? 0 : v << n; }
static inline uint64_t SHR(uint64_t v, uint64_t n) { return n >= 64 ? 0 : v >> n; }
static inline uint64_t SAR(int64_t v, uint64_t n) { return (uint64_t)(n >= 64 ? (v < 0 ? -1 : 0) : v >> n); }
static inline uint64_t MASKN(int size) { return size >= 8 ? ~0ULL : (1ULL << (8 * size)) - 1; }
static inline uint64_t CARRY(uint64_t a, uint64_t b, int size) {
    uint64_t m = MASKN(size); a &= m; b &= m; return ((a + b) & m) < a;
}
static inline uint64_t SCARRY(uint64_t a, uint64_t b, int size) {
    int64_t x = SEXT(a, size), y = SEXT(b, size), s = SEXT((uint64_t)(x + y), size);
    return (x >= 0) == (y >= 0) && (s >= 0) != (x >= 0);
}
static inline uint64_t SBORROW(uint64_t a, uint64_t b, int size) {
    int64_t x = SEXT(a, size), y = SEXT(b, size), s = SEXT((uint64_t)(x - y), size);
    return (x >= 0) != (y >= 0) && (s >= 0) != (x >= 0);
}
_Noreturn void rt_divide_error(void);
static inline uint64_t RT_UDIV(uint64_t a, uint64_t b) { if (!b) rt_divide_error(); return a / b; }
static inline uint64_t RT_UREM(uint64_t a, uint64_t b) { if (!b) rt_divide_error(); return a % b; }
static inline int64_t RT_SDIV(int64_t a, int64_t b) { if (!b) rt_divide_error(); return a / b; }
static inline int64_t RT_SREM(int64_t a, int64_t b) { if (!b) rt_divide_error(); return a % b; }

/* ---- control flow ------------------------------------------------------------ */
/* CALL: the p-code has already pushed the return address; check that the
 * callee's RET popped exactly that. */
_Noreturn void rt_bad_return(uint32_t expected, uint32_t got);
#define RT_CALL(fn, ret) do { fn(); if (cpu.ret_addr != (ret)) rt_bad_return((ret), cpu.ret_addr); } while (0)
#define RT_RET(addr) (cpu.ret_addr = (addr))

void rt_callind(uint32_t target, uint32_t ret);     /* computed call      */
void rt_jumpind(uint32_t target);                   /* unknown computed jump */
void rt_callother(unsigned kind, uint32_t at, ...); /* special instructions */
rt_func rt_lookup(uint32_t addr);

/* Supplied by the host (shell / platform layer): called for computed calls to
 * addresses outside the core, i.e. ILT slots 0x401000..0x401244. The host must
 * not touch ESP; rt_callind pops the return address. */
void host_shell_call(uint32_t ilt_addr);
